ng"},"status":{"description":"Legacy alias of state: pending|in_progress|completed.","type":"string"},"title":{"description":"One step. ('content' is also accepted.)","type":"string"}},"type":"object"},"type":"array"},"kind":{"description":"op=note: the note's kind.","enum":["decision","finding","assumption"],"type":"string"},"op":{"description":"set (default): replace the whole plan. update: merge the listed items by id, changing only the fields given. note: record a decision, finding or assumption. next: record what comes next. done: mark one item done with evidence. handoff: continue in a fresh context from `brief`.","enum":["set","update","note","next","done","handoff"],"type":"string"},"text":{"description":"op=note (≤1000 chars) / op=next (≤600 chars): the recorded text.","type":"string"}},"type":"object"},"name":"plan"}
